#include <iostream>
#include <vector>
#include <string>
#include <unordered_map>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<string> passwords(n);
    for (int i = 0; i < n; ++i) {
        cin >> passwords[i];
    }

    // 特判：所有口令完全相同
    string first = passwords[0];
    bool allSame = true;
    for (int i = 1; i < n; ++i) {
        if (passwords[i] != first) {
            allSame = false;
            break;
        }
    }
    if (allSame) {
        cout << n - 1 << '\n';
        return 0;
    }

    // 统计每个口令的连续段长度
    unordered_map<string, vector<int>> seg;
    string cur = passwords[0];
    int len = 1;
    for (int i = 1; i < n; ++i) {
        if (passwords[i] == cur) {
            ++len;
        } else {
            seg[cur].push_back(len);
            cur = passwords[i];
            len = 1;
        }
    }
    seg[cur].push_back(len);  // 最后一段

    int maxAns = 0;
    for (auto &entry : seg) {
        auto &lengths = entry.second;
        sort(lengths.rbegin(), lengths.rend());  // 降序
        if (lengths.size() == 1) {
            maxAns = max(maxAns, lengths[0]);
        } else {
            maxAns = max(maxAns, lengths[0] + lengths[1]);
        }
    }
    cout << maxAns << '\n';
    return 0;
}
